+            sql += " and INDEX_CATALOG='" + database.escapeStringForDatabase(catalogName) + "'";
+        }
+        if (tableName != null) {
+            sql += " and TABLE_NAME='" + database.escapeStringForDatabase(database.correctObjectName(tableName, Table.class)) + "'";
+        }
+        if (exampleName != null) {
+            sql += " and INDEX_NAME='" + database.escapeStringForDatabase(exampleName) + "'";
+        }
+        sql += " order by INDEX_NAME, ORDINAL_POSITION";
+
+        List<Map<String, ?>> rows = Scope.getCurrentScope().getSingleton(ExecutorService.class)
+                .getExecutor("jdbc", database)
+                .queryForList(new RawSqlStatement(sql));
+        Map<String, Index> foundIndexes = new HashMap<>();
+        for (Map<String, ?> row : rows) {
